/* ---------- calculator ---------- */
function curPill(code){
 if(code==='RUB')return '<span class="curpill fixed"><b class="rubmark">₽</b><span>RUB</span></span>';
 var c=CUR[code];
 return '<button class="curpill" data-act="sheet:cur" aria-haspopup="dialog" aria-label="Выбрать криптовалюту">'+cdot(code,24)+'<span>'+c.coin+'<small>'+esc(c.net)+'</small></span>'+ic('chevd',18)+'</button>'}
function chipsHTML(){return '<div class="chips6" role="group" aria-label="Сумма в рублях">'+CHIPS.map(function(v,i){return '<button class="chip'+(QBARS[i]===1?' slow':'')+'" data-act="chip:'+i+'" aria-pressed="'+(S.amount===v)+'"><span class="num">'+nf(v,0)+' ₽</span><span class=\"ct\">'+ic('clock',11)+ETA[QBARS[i]][0]+'</span></button>'}).join('')+'</div>'}
function etaHTML(){var i=CHIPS.indexOf(S.amount);if(i<0)return '<div class="eta">'+ic('clock',18)+'<span>Выберите сумму, чтобы увидеть ожидаемое время обмена</span></div>';var e=ETA[QBARS[i]];return '<div class="eta">'+ic('clock',20)+'<span><b>'+e[0]+'</b>'+e[1]+'. Время примерное, считаем по встречным заявкам сейчас</span></div>'}
function calcHTML(){
 if(!S.working)return '<section class="calc sleep" aria-label="Обмен недоступен"><span class="moon">'+ic('moon',34)+'</span><h3>Обмены сейчас недоступны</h3><p>Мы работаем <b>10:00–18:30 GMT+3</b>. Если у вас уже есть активный обмен, проверьте его статус в разделе <a href="#" data-act="go:orders">Мои обмены</a>.</p></section>';
 var cc=S.coin;
 return '<section class="calc grouped" aria-label="Калькулятор обмена">'+
  '<div class="pairbox">'+
   '<div class="crow"><div class="cl"><span class="lbl">Отдаю</span><span class="amt num">'+sideStr('give')+'</span></div>'+curPill(giveC())+'</div>'+
   '<div class="divider"><button class="swapbtn" data-act="swap" aria-label="Поменять местами">'+ic('swapv',20)+'</button></div>'+
   '<div class="crow"><div class="cl"><span class="lbl">Получаю</span><span class="amt num">'+sideStr('get')+'</span></div>'+curPill(getC())+'</div>'+
   '<div class="rateline"><span><b class="num">'+rateStr(cc)+'</b></span><span class="badge">'+ic('checkb',12)+'с учётом комиссии</span></div>'+
  '</div>'+
  '<div class="amtgrp"><div class="ghead"><b>Сумма в рублях</b><span>'+ic('clock',12)+'время ожидания</span></div>'+chipsHTML()+etaHTML()+'</div>'+
  '<button class="btn calcbtn" data-act="home-continue"'+(S.amount==null?' disabled':'')+'>Продолжить</button></section>'}

var PARTNERS=[['BestChange','Мониторинг обменников'],['OKchanger','Мониторинг обменников'],['КурсЕксперт','Анализатор обменников'],['GLAZOK','Мониторинг обменников']];
var SECIMG='data:image/jpeg;base64,';
var SECS=[['card','Не разрешаем использовать чужие карты','Сверяем данные в личном кабинете и чеках, просим вас сверить получателя фиата.'],
 ['bank','Автоматически проверяем подлинность перевода','Для отправки доступны только те банки, которые минимизируют возможность подделки перевода.'],
 ['closec','Блокируем нарушителей','Пользователи, нарушившие правила, больше не смогут совершать обмен.']];
function secHTML(){var w=SECS;
 return '<section class="secb" aria-labelledby="sech"><div class="sbn"><img src="'+SECIMG+'" alt="" width="720" height="480"><h3 id="sech">Почему обмен в Libre.zone <em>безопасен</em>?</h3></div>'+
  '<div class="sslider" id="ssl">'+w.map(function(t){return '<div class="ss"><span class="si">'+ic(t[0],20)+'</span><b>'+t[1]+'</b><span>'+t[2]+'</span></div>'}).join('')+'</div>'+
  '<div class="sdots" role="tablist" aria-label="Безопасность">'+w.map(function(t,i){return '<button role="tab" aria-label="'+(i+1)+' из '+w.length+'" data-act="sdot:'+i+'" class="'+(i===0?'on':'')+'"></button>'}).join('')+'</div></section>'}
var WHYS=[['chart','Курс фиксируется при создании обмена','Сумма к оплате не изменится, пока идёт обмен. Комиссия уже в курсе.'],
 ['bank','Получение на любой банк РФ по СБП','Выплата по номеру телефона в любой банк, подключённый к СБП.'],
 ['idoff','Не требуются селфи и документы','Для обмена достаточно телефона, ФИО и email.'],
 ['shield','Тщательная проверка данных и безопасность','Каждый обмен проходит проверку, данные передаются по защищённому соединению.'],
 ['percent','Отсутствие скрытых комиссий','Итоговую сумму вы видите до оплаты. Больше ничего не спишем.']];
function whyHTML(){var w=WHYS;
 if(WHY==='list')return '<div class="card wlist">'+w.map(function(t){return '<div class="wrow"><span class="wi2">'+ic(t[0],20)+'</span><div><b>'+t[1]+'</b><span>'+t[2]+'</span></div></div>'}).join('')+'</div>';
 if(WHY==='bento')return '<div class="wbento">'+w.map(function(t,i){return '<div class="wb'+(i===0?' wide':'')+'"><span class="wi2">'+ic(t[0],20)+'</span><b>'+t[1]+'</b>'+(i===0?'<span>'+t[2]+'</span>':'')+'</div>'}).join('')+'</div>';
 var cls=WHY==='carousel'?'wslider peek':'wslider';
 return '<div class="'+cls+'" id="wsl">'+w.map(function(t,i){return '<div class="ws"><span class="wi2">'+ic(t[0],24)+'</span><b>'+t[1]+'</b><span>'+t[2]+'</span></div>'}).join('')+'</div>'+
  '<div class="wdots" role="tablist" aria-label="Преимущества">'+w.map(function(t,i){return '<button role="tab" aria-label="'+(i+1)+' из '+w.length+'" data-act="wdot:'+i+'" class="'+(i===0?'on':'')+'"></button>'}).join('')+'</div>'}
function homeHTML(){
 var tiles=[['wallet','Вывести зарплату из РФ','Надёжный способ перевести рубли в крипту'],['users','Перевести рубли родствен&shy;никам','Получите рубли на карту и отправьте близким'],['coins','Войти в крипто&shy;инвестиции','Операции с криптой без сложных регистраций'],['card','Небольшие суммы для подписок','Купите крипту для оплаты зарубежных сервисов']];
 var how=[['01','Выберите сумму','Из фиксированных'],['02','Укажите реквизиты','Банк и адрес'],['03','Получите обмен','Следите за статусом']];
 var whys=WHYS;
 var body='<section class="hero"><h1>Криптообмены с <em>фиксированными</em> суммами</h1><p>Обменивайте криптовалюту по понятным и честным правилам. Просто. Быстро. Безопасно.</p>'+orbit()+'</section>'+calcHTML()+
  '<div style="margin:12px 16px 0">'+(S.working?dchips('Демо-сценарии',[['Покупка USDT','calc:buy'],['Продажа USDT','calc:sell'],['BTC на 50 000 ₽','calc:btc'],['ETH на 10 000 ₽','calc:eth'],['Вне часов','calc:off']]):dchips('Демо-сценарии',[['Включить обмены','calc:on']]))+'</div>'+
  hoursHTML()+
  '<h3 class="sec">Для любых задач</h3><div class="tiles">'+tiles.map(function(t){return '<div class="tile"><span class="ti">'+ic(t[0],20)+'</span><b>'+t[1]+'</b><span>'+t[2]+'</span></div>'}).join('')+'</div>'+secHTML()+
  '<h3 class="sec">Почему Libre.zone?</h3>'+whyHTML()+
  '<h3 class="sec">Наши партнёры</h3><div class="partners">'+PARTNERS.map(function(p,i){return '<a class="partner" href="#" data-act="partner:'+esc(p[0])+'"><span class="top"><span class="pn">0'+(i+1)+'</span><span class="go">'+ic('ext',16)+'</span></span><span><b>'+esc(p[0])+'</b><small>'+esc(p[1])+'</small></span></a>'}).join('')+'</div>'+
  '<div class="foot">support@libre.zone · поддержка 10:00–18:30 МСК<br><a href="#" data-act="doc:rules">Правила</a> · <a href="#" data-act="doc:privacy">Политика конфиденциальности</a> · <a href="#" data-act="doc:aml">AML</a></div>';
 return nav(true)+'<div class="content flush" id="scroller">'+body+'</div>';
}

